{
  "name": "@vymalo/opencode-ratelimit",
  "version": "0.20.2",
  "description": "OpenCode plugin that makes OpenAI-compatible providers rate-limit aware: it reads Envoy Gateway / IETF draft-03 rate-limit response headers (x-ratelimit-limit/remaining/reset), proactively throttles requests when the quota is exhausted, and backs off and retries on HTTP 429.",
  "license": "MIT",
  "author": "vymalo contributors",
  "homepage": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit.git",
    "directory": "packages/opencode-ratelimit"
  },
  "bugs": {
    "url": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "rate-limit",
    "throttle",
    "429",
    "envoy",
    "ai-sdk"
  ],
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./lib": {
      "types": "./dist/lib.d.ts",
      "import": "./dist/lib.js"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.6"
  },
  "devDependencies": {
    "effect": "4.1.0",
    "vite": "^8.3.0",
    "vitest": "^5.0.1"
  },
  "peerDependencies": {
    "effect": "^4.0.0"
  },
  "scripts": {
    "build": "node ../../scripts/build-package.mjs",
    "lint": "biome lint .",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "coverage": "vitest run --coverage",
    "format": "biome format --write .",
    "format:check": "biome format ."
  }
}
